  delBtn.textContent = '删除';
  delBtn.style.marginLeft = '10px';
  delBtn.addEventListener('click', function() {
    li.remove();
  });

  li.appendChild(span);
  li.appendChild(delBtn);
  todos.appendChild(li);

  input.value = '';
  input.focus();
}

