// 实际应用：组件通信
class Counter {
  constructor() {
    this.count = 0;
    this.el = document.createElement('div');
  }

  increment() {
    this.count++;
    // 触发自定义事件通知外部
    let event = new CustomEvent('countChange', {
      detail: { count: this.count },
      bubbles: true
    });
    this.el.dispatchEvent(event);
  }
}

