let box = document.getElementById('box');
let startTime = null;
let duration = 2000; // 动画持续2秒

// 简单的位移动画
function animate(timestamp) {
  if (!startTime) startTime = timestamp;
  let progress = (timestamp - startTime) / duration; // 0到1的进度

  if (progress < 1) {
    // 线性动画
    box.style.left = (progress * 300) + 'px'; // 移动300px
    requestAnimationFrame(animate);
  } else {
    box.style.left = '300px';
  }
}
requestAnimationFrame(animate);

// 缓动函数（easing）
function easeInOut(t) {
  return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
}

function animateEase(timestamp) {
  if (!startTime) startTime = timestamp;
  let progress = Math.min((timestamp - startTime) / duration, 1);
  let eased = easeInOut(progress); // 应用缓动
  box.style.left = (eased * 300) + 'px';
  if (progress < 1) requestAnimationFrame(animateEase);
}

// 封装动画函数
function animateValue(element, prop, from, to, duration, easing) {
  let start = null;
  easing = easing || (t => t); // 默认线性

  function step(timestamp) {
    if (!start) start = timestamp;
    let progress = Math.min((timestamp - start) / duration, 1);
    let value = from + (to - from) * easing(progress);
    element.style[prop] = value + 'px';
    if (progress < 1) requestAnimationFrame(step);
  }
  requestAnimationFrame(step);
}

// 使用
