  let res = await fetch(API, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(data)
  });
  let user = await res.json();
  console.log('创建成功：', user);
  fetchUsers(); // 刷新列表
}

// 更新用户
async function updateUser(id, data) {
  let res = await fetch(`${API}/${id}`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(data)
  });
  let user = await res.json();
  console.log('更新成功：', user);
  fetchUsers();
}

// 删除用户
async function deleteUser(id) {
  let res = await fetch(`${API}/${id}`, { method: 'DELETE' });
  if (res.ok) {
    console.log('删除成功');
    fetchUsers();
  }
}

// 事件委托处理编辑/删除
document.getElementById('userList').addEventListener('click', async (e) => {
  let li = e.target.closest('li');
  let id = li.dataset.id;

  if (e.target.classList.contains('del')) {
    if (confirm('确定删除？')) {
      await deleteUser(id);
    }
  } else if (e.target.classList.contains('edit')) {
    let name = prompt('输入新名字：');
    if (name) {
      await updateUser(id, { name });
    }
  }
});

// 提交表单创建用户
document.getElementById('userForm').addEventListener('submit', async (e) => {
  e.preventDefault();
  let formData = new FormData(e.target);
  let data = Object.fromEntries(formData.entries());
  await createUser(data);
  e.target.reset();
});

// 初始化
fetchUsers();

let todos = JSON.parse(localStorage.getItem('todos')) || [];
let currentFilter = 'all'; // all / active / completed

const STORAGE_KEY = 'todos';

// 保存到localStorage
function save() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
}

// 生成任务id
function genId() {
  return Date.now() + Math.random().toString(36).substr(2, 5);
}

// 添加任务
function addTodo(text) {
  if (!text.trim()) return;
  todos.unshift({  // 加到最前面
    id: genId(),
    text: text.trim(),
    done: false
  });
  save();
  render();
}

// 切换完成状态
function toggleTodo(id) {
  let todo = todos.find(t => t.id === id);
  if (todo) {
    todo.done = !todo.done;
    save();
    render();
  }
}

// 删除任务
function deleteTodo(id) {
  todos = todos.filter(t => t.id !== id);
  save();
  render();
}

// 编辑任务
function editTodo(id, newText) {
  let todo = todos.find(t => t.id === id);
  if (todo && newText.trim()) {
    todo.text = newText.trim();
    save();
    render();
  }
}

// 清除已完成
function clearCompleted() {
  todos = todos.filter(t => !t.done);
  save();
  render();
}

// 渲染列表
function render() {
  let list = document.getElementById('todoList');

  // 根据过滤条件筛选
  let filtered = todos.filter(t => {
    if (currentFilter === 'active') return !t.done;
    if (currentFilter === 'completed') return t.done;
    return true;
  });

  // 空状态
  if (filtered.length === 0) {
    list.innerHTML = '<li class="empty">暂无任务</li>';
  } else {
    list.innerHTML = filtered.map(t => `
      <li class="todo-item ${t.done ? 'done' : ''}" data-id="${t.id}">
        <input type="checkbox" ${t.done ? 'checked' : ''} class="toggle">
        <span class="todo-text">${escapeHtml(t.text)}</span>
        <button class="del-btn">✕</button>
      </li>
    `).join('');
  }

  // 更新统计
  let activeCount = todos.filter(t => !t.done).length;
  document.getElementById('count').textContent = `${activeCount} 项未完成`;
}

// 转义HTML防止XSS
function escapeHtml(str) {
  let div = document.createElement('div');
  div.textContent = str;
  return div.innerHTML;
}

let todoInput = document.getElementById('todoInput');
let addBtn = document.getElementById('addBtn');
let todoList = document.getElementById('todoList');
let clearBtn = document.getElementById('clearBtn');

// 添加任务
addBtn.addEventListener('click', () => {
  addTodo(todoInput.value);
  todoInput.value = '';
  todoInput.focus();
});

todoInput.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') {
    addTodo(todoInput.value);
    todoInput.value = '';
  }
});

// 列表事件委托
todoList.addEventListener('click', (e) => {
  let li = e.target.closest('.todo-item');
  if (!li) return;
  let id = li.dataset.id;

  // 点击复选框
  if (e.target.classList.contains('toggle')) {
    toggleTodo(id);
  }
  // 点击删除
  else if (e.target.classList.contains('del-btn')) {
    deleteTodo(id);
  }
});

// 双击进入编辑
todoList.addEventListener('dblclick', (e) => {
  if (!e.target.classList.contains('todo-text')) return;

  let li = e.target.closest('.todo-item');
  let id = li.dataset.id;
  let todo = todos.find(t => t.id === id);
  if (!todo || todo.done) return; // 已完成不能编辑

  // 替换为输入框
  let input = document.createElement('input');
  input.className = 'todo-edit';
  input.value = todo.text;
  e.target.replaceWith(input);
  input.focus();
  input.select();

  // 保存编辑
  function saveEdit() {
    editTodo(id, input.value);
  }
  input.addEventListener('blur', saveEdit);
  input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') saveEdit();
    if (e.key === 'Escape') render(); // 取消，重新渲染
  });
});

// 过滤按钮
document.querySelectorAll('.filter').forEach(btn => {
  btn.addEventListener('click', () => {
    document.querySelectorAll('.filter').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    currentFilter = btn.dataset.filter;
    render();
  });
});

// 清除已完成
clearBtn.addEventListener('click', () => {
  if (todos.filter(t => t.done).length === 0) {
    alert('没有已完成的任务');
    return;
  }
  if (confirm('确定清除所有已完成的任务？')) {
    clearCompleted();
  }
});

