render();

// 扩展：用Fetch同步数据到服务器
const API_URL = '/api/todos';

// 从服务器加载
async function loadFromServer() {
  try {
    let res = await fetch(API_URL);
    if (res.ok) {
      let serverTodos = await res.json();
      // 合并本地和服务器数据（简单策略：服务器优先）
      todos = serverTodos;
      save();
      render();
    }
  } catch (e) {
    console.log('离线模式，使用本地数据');
  }
}

// 同步到服务器
async function syncToServer(action, todo) {
  try {
    await fetch(API_URL, {
      method: action === 'delete' ? 'DELETE' : 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(todo)
    });
  } catch (e) {
    // 网络错误，加入待同步队列
    pendingSync.push({ action, todo });
    console.log('已加入待同步队列');
  }
}

// 修改addTodo，加上服务器同步
async function addTodoOnline(text) {
  if (!text.trim()) return;
  let todo = { id: genId(), text: text.trim(), done: false };
  todos.unshift(todo);
  save();  // 先保存本地
  render(); // 立即更新视图（乐观更新）
  await syncToServer('create', todo); // 异步同步服务器
}

// 网络恢复后同步待处理队列
let pendingSync = [];
window.addEventListener('online', async () => {
  console.log('网络恢复，开始同步');
  while (pendingSync.length > 0) {
    let { action, todo } = pendingSync.shift();
    await syncToServer(action, todo);
  }
});

// 监听离线
window.addEventListener('offline', () => {
  console.log('网络断开，进入离线模式');
});

